DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_booking_baru` (IN `p_id_user` INT, IN `p_id_trip` INT)   BEGIN
    DECLARE v_kapasitas INT;
    DECLARE v_harga DECIMAL(12,2);
 
    SELECT kapasitas_tersisa, harga INTO v_kapasitas, v_harga
    FROM open_trip WHERE id_trip = p_id_trip;
 
    IF v_kapasitas IS NULL THEN
        SELECT 'Trip tidak ditemukan' AS pesan;
    ELSEIF v_kapasitas > 0 THEN
        INSERT INTO booking (id_user, id_trip, jumlah_peserta, total_harga, status)
        VALUES (p_id_user, p_id_trip, 1, v_harga, 'pending');
 
        UPDATE open_trip
        SET kapasitas_tersisa = kapasitas_tersisa - 1
        WHERE id_trip = p_id_trip;
 
        SELECT CONCAT('Booking berhasil untuk user ', p_id_user) AS pesan;
    ELSE
        SELECT 'Kuota trip sudah habis' AS pesan;
    END IF;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_klasifikasi_rating_wisata` ()   BEGIN
    DECLARE v_done INT DEFAULT 0;
    DECLARE v_id_wisata INT;
    DECLARE v_nama VARCHAR(150);
    DECLARE v_rating DECIMAL(2,1);
    DECLARE v_status VARCHAR(20);
 
    DECLARE cur_wisata CURSOR FOR
        SELECT id_wisata, nama_wisata, rating FROM wisata;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;
 
    DELETE FROM wisata_status_log; -- reset supaya hasil selalu terbaru
 
    OPEN cur_wisata;
 
    baca_loop: LOOP
        FETCH cur_wisata INTO v_id_wisata, v_nama, v_rating;
        IF v_done = 1 THEN
            LEAVE baca_loop;
        END IF;
 
        CASE
            WHEN v_rating >= 4.5 THEN SET v_status = 'Sangat Baik';
            WHEN v_rating >= 3.5 THEN SET v_status = 'Baik';
            WHEN v_rating >= 2.5 THEN SET v_status = 'Cukup';
            ELSE SET v_status = 'Kurang';
        END CASE;
 
        INSERT INTO wisata_status_log (id_wisata, nama_wisata, rating, status_rating)
        VALUES (v_id_wisata, v_nama, v_rating, v_status);
    END LOOP;
 
    CLOSE cur_wisata;
 
    SELECT * FROM wisata_status_log;
END$$

--
-- Functions
--
CREATE DEFINER=`root`@`localhost` FUNCTION `fn_hitung_harga_diskon` (`p_harga` DECIMAL(10,2), `p_persen_diskon` INT) RETURNS DECIMAL(10,2) DETERMINISTIC BEGIN
    DECLARE hasil DECIMAL(10,2);
    SET hasil = p_harga - (p_harga * p_persen_diskon / 100);
    RETURN hasil;
END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_jumlah_wisata_aktif` () RETURNS INT(11) DETERMINISTIC READS SQL DATA BEGIN
    DECLARE total INT;
    SELECT COUNT(*) INTO total FROM wisata WHERE status = 'aktif';
    RETURN total;
END$$

DELIMITER ;

