--
-- Triggers `booking`
--
DELIMITER $$
CREATE TRIGGER `trg_after_insert_booking` AFTER INSERT ON `booking` FOR EACH ROW BEGIN
    INSERT INTO log_aktivitas (nama_tabel, aksi, keterangan)
    VALUES ('booking', 'INSERT',
            CONCAT('Booking baru id=', NEW.id_booking, ' user=', NEW.id_user,
                   ' trip=', NEW.id_trip, ' total=', NEW.total_harga));
 
    UPDATE open_trip
    SET kapasitas_tersisa = kapasitas_tersisa - NEW.jumlah_peserta
    WHERE id_trip = NEW.id_trip AND kapasitas_tersisa >= NEW.jumlah_peserta;
END
$$
DELIMITER ;

