(1, 6, 'Tari Serimpi', 'tari-serimpi', 'Yogyakarta', 'Tari klasik keraton yang dibawakan secara lembut dan anggun oleh 4 penari putri.', 'Berkembang di lingkungan Keraton Yogyakarta sejak abad ke-18 sebagai tari istana.', '/uploads/budaya/serimpi.jpg', 'aktif', '2026-07-15 02:05:00', '2026-07-15 02:05:00'),
(2, 6, 'Tari Bedhaya', 'tari-bedhaya', 'Yogyakarta', 'Tari sakral keraton yang dibawakan 9 penari sebagai simbol penghormatan kepada raja.', 'Merupakan tari pusaka Keraton Yogyakarta yang hanya ditampilkan pada upacara tertentu.', '/uploads/budaya/bedhaya.jpg', 'aktif', '2026-07-15 02:05:00', '2026-07-15 02:05:00'),
(3, 7, 'Gamelan Jawa', 'gamelan-jawa', 'Yogyakarta', 'Ansambel musik tradisional dengan instrumen perunggu seperti gong, saron, dan bonang.', 'Telah menjadi bagian budaya Jawa sejak masa kerajaan Mataram dan terus dilestarikan hingga kini.', '/uploads/budaya/gamelan.jpg', 'aktif', '2026-07-15 02:05:00', '2026-07-15 02:05:00'),
(4, 8, 'Batik Yogyakarta', 'batik-yogyakarta', 'Yogyakarta', 'Kain batik dengan motif klasik seperti parang dan kawung, diakui UNESCO sebagai warisan dunia.', 'Berkembang di lingkungan keraton sejak abad ke-17 sebagai busana bangsawan.', '/uploads/budaya/batik.jpg', 'aktif', '2026-07-15 02:05:00', '2026-07-15 02:05:00'),
(5, 8, 'Kerajinan Perak Kotagede', 'kerajinan-perak-kotagede', 'Kotagede, Yogyakarta', 'Sentra kerajinan perak dengan teknik filigree yang telah dikenal sejak masa Mataram Islam.', 'Kotagede menjadi pusat kerajinan perak sejak era Kesultanan Mataram abad ke-16.', '/uploads/budaya/perak.jpg', 'aktif', '2026-07-15 02:05:00', '2026-07-15 02:05:00'),
(6, 9, 'Upacara Sekaten', 'upacara-sekaten', 'Yogyakarta', 'Upacara adat memperingati kelahiran Nabi Muhammad SAW yang digelar tiap tahun di alun-alun.', 'Diperkenalkan oleh Kesultanan Demak dan diteruskan Keraton Yogyakarta sebagai media dakwah.', '/uploads/budaya/sekaten.jpg', 'aktif', '2026-07-15 02:05:00', '2026-07-15 02:05:00'),
(7, 9, 'Grebeg Maulud', 'grebeg-maulud', 'Yogyakarta', 'Prosesi kirab gunungan hasil bumi dari keraton sebagai wujud syukur dan sedekah kepada rakyat.', 'Tradisi ini telah berlangsung turun-temurun sejak masa Kesultanan Mataram Islam.', '/uploads/budaya/grebeg.jpg', 'aktif', '2026-07-15 02:05:00', '2026-07-15 02:05:00'),
(8, 10, 'Gudeg', 'gudeg', 'Yogyakarta', 'Makanan khas berbahan dasar nangka muda yang dimasak dengan santan selama berjam-jam.', 'Gudeg dipercaya sudah ada sejak masa pembangunan Kesultanan Mataram di Alas Mentaok.', '/uploads/budaya/gudeg.jpg', 'aktif', '2026-07-15 02:05:00', '2026-07-15 02:05:00'),
(9, 10, 'Bakpia Pathok', 'bakpia-pathok', 'Yogyakarta', 'Kue kering berisi kacang hijau yang menjadi oleh-oleh khas dari kawasan Pathok, Yogyakarta.', 'Dibawa oleh warga keturunan Tionghoa pada awal abad ke-20 dan berkembang menjadi kuliner khas.', '/uploads/budaya/bakpia.jpg', 'aktif', '2026-07-15 02:05:00', '2026-07-15 02:05:00'),
(10, 14, 'Kain Lurik', 'kain-lurik', 'Yogyakarta', 'Kain tenun tradisional bermotif garis yang biasa digunakan sebagai pakaian sehari-hari masyarakat Jawa.', 'Lurik telah ditenun sejak zaman kerajaan Jawa kuno sebagai simbol kesederhanaan.', '/uploads/budaya/lurik.jpg', 'aktif', '2026-07-15 02:05:00', '2026-07-15 02:05:00');

