--
-- Triggers `wisata`
--
DELIMITER $$
CREATE TRIGGER `trg_before_update_wisata` BEFORE UPDATE ON `wisata` FOR EACH ROW BEGIN
    IF NEW.harga_tiket < 0 THEN
        SET NEW.harga_tiket = OLD.harga_tiket; -- tolak harga negatif, kembalikan ke harga lama
    END IF;
    IF NEW.rating > 5 THEN
        SET NEW.rating = 5.0; -- rating tidak boleh lebih dari 5
    END IF;
END
$$
DELIMITER ;

